def solve(n):
    """Return the count of prime numbers strictly less than n.
    Uses a memory‑efficient sieve based on bytearray.
    """
    if n <= 2:
        return 0
    # Bytearray where 1 means potential prime
    is_prime = bytearray(b'\x01') * n
    is_prime[0:2] = b'\x00\x00'  # 0 and 1 are not prime
    limit = int(n ** 0.5) + 1
    for i in range(2, limit):
        if is_prime[i]:
            start = i * i
            step = i
            is_prime[start:n:step] = b'\x00' * ((n - start - 1) // step + 1)
    return sum(is_prime)

